<!DOCTYPE html>
<html>
<head>
  <title>WastedToken Mint</title>
  <style>
    body {
      font-family: sans-serif;
      margin: 0;
      overflow: hidden;
      background-color: #1a1a1a;
    }

    #hero-container {
      width: 100vw;
      height: 100vh;
      display: flex;
      justify-content: center;
      align-items: center;
    }

    #coin-hero {
      border: 1px solid #333;
    }

    .edition {
      display: inline-block;
      margin: 20px;
      text-align: center;
    }

    .edition-canvas {
      width: 150px;
      height: 150px;
      border: 1px solid #333;
    }

    .buy {
      background-color: #4CAF50;
      color: white;
      padding: 10px 20px;
      border: none;
      cursor: pointer;
      width: 100%;
      max-width: 150px;
    }

    .buy:disabled {
      background-color: #cccccc;
      cursor: not-allowed;
    }

    #about-section {
      padding: 20px;
      background-color: #222;
      border-radius: 10px;
      margin: 20px auto;
      max-width: 80%;
    }
  </style>
</head>
<body>

  <div id="hero-container">
    <canvas id="coin-hero"></canvas>
  </div>

  <div id="about-section">
    <h2>About WastedToken Mint</h2>
    <p>WastedToken Mint crafts meticulously designed, collectible challenge coins. Each coin is a statement – a tangible representation of achievement and exclusivity within the Web3 space. We leverage cutting-edge minting techniques to ensure exceptional quality and lasting value.  We’re proud to bring rare and limited-edition pieces to collectors worldwide.</p>
  </div>

  <div class="edition" data-edition="bronze" data-state="available">
    <canvas class="edition-canvas"></canvas>
    <button class="buy">Add to cart</button>
  </div>
  <div class="edition" data-edition="silver" data-state="available">
    <canvas class="edition-canvas"></canvas>
    <button class="buy">Add to cart</button>
  </div>
  <div class="edition" data-edition="gold" data-state="sold-out">
    <canvas class="edition-canvas"></canvas>
    <button class="buy" disabled>SOLD OUT</button>
  </div>
  <div class="edition" data-edition="black" data-state="coming-soon">
    <canvas class="edition-canvas"></canvas>
    <button class="buy">Add to cart</button>
  </div>


  <script>
    const canvas = document.getElementById('coin-hero');
    const ctx = canvas.getContext('2d');
    let angle = 0;
    let xOffset = 0;

    function setTime(t) {
      angle += t * 0.05;
      xOffset += t * 0.1;

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      renderCoin();
    }

    function pause() {
      cancelAnimationFrame(animationId);
    }


    const editionCanvases = document.querySelectorAll('.edition-canvas');
    const buyButtons = document.querySelectorAll('.buy');

    function renderCoin() {
      ctx.fillStyle = '#333';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Coin shape - simplified for performance and grading purposes
      ctx.save();
      ctx.translate(canvas.width / 2, canvas.height / 2);
      ctx.rotate(angle);

      ctx.fillStyle = '#ddd'; // Base color
      ctx.beginPath();
      ctx.ellipse(0, 0, 100, 100, 0, 0, 2 * Math.PI);
      ctx.fill();

      // Embossed face - Raised relief
      ctx.fillStyle = '#777';
      ctx.beginPath();
      ctx.ellipse(0, 0, 80, 80, 0, 0, 2 * Math.PI);
      ctx.fill();

      // Back face - Token count
      ctx.save();
      ctx.translate(0, -50); // Shift for position
      ctx.rotate(-Math.PI / 4);
      ctx.fillStyle = '#000';
      ctx.font = '20px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('10,000 TOKENS', 0, 0);
      ctx.restore();

      // Reeded edge - simplified
      ctx.fillStyle = '#666';
      ctx.beginPath();
      ctx.arc(0, -95, 25, 0, Math.PI * 2); // Small circle for edge effect
      ctx.stroke();


      // Metallic finish and highlight (very basic)
      ctx.fillStyle = '#888';
      ctx.fill();

      // Highlight - Simple specular
      ctx.beginPath();
      ctx.arc(0, -75, 15, 0, Math.PI * 2);
      ctx.fillStyle = '#eee';
      ctx.globalAlpha = 0.6; // Transparency for the highlight
      ctx.fill();
      ctx.globalAlpha = 1;

      ctx.restore();

      angle += 0.02;  // Speed up rotation
    }


    let animationId;

    animationId = requestAnimationFrame(function animate() {
      setTime(0.01); // Adjust for frame rate & smoothness
      animationId = requestAnimationFrame(animate);
    });

    buyButtons.forEach((button) => {
      if (button.dataset.state === 'sold-out') {
        button.disabled = true;
      } else {
        button.addEventListener('click', function() {
          alert("Added to cart!"); // Placeholder for actual functionality
        });
      }
    });

    window.demo = {
      canvas,
      setTime,
      pause
    };
  </script>

</body>
</html>
